    public void run()
    {
        // MPJ_22903_SalesOrderGuide
        if(!this.metCheckOrderGuides())
        {
            throw Exception::Error;
        }

        next run();
    }

/// <summary>
/// MPJ_22903_SalesOrderGuide - Pre checks/updates related to order guides.
/// </summary>
/// <returns></returns>
private boolean metCheckOrderGuides()
{
    boolean ret = METSalesOrderGuideExecution::applyChecksToOrder(salesParmTable.SalesID);
    return ret;
}
